async () => {
const sleep=ms=>new Promise(r=>setTimeout(r,ms));
const targets=['barbara.lindqvist@laboratory.example','walter.brennan@laboratory.example','louisa.lindqvist@laboratory.example','marguerite.bennett@laboratory.example','eula.selvi@laboratory.example'];
const g=document.querySelector('vaadin-grid'); const log=[];
for(const email of targets){
  let found=null;
  for(let i=0;i<g.size && !found;i+=10){ g.scrollToIndex(i); await sleep(350);
    for(const r of g._getRenderedRows()){ const cells=[...r.children].map(c=>c._content?c._content.textContent:''); if(cells[2]===email && cells[3]==='Closed (lost)' && cells[4].startsWith('Laboratory')){found=r;break;} } }
  if(!found){log.push('notfound '+email);continue;}
  found.children[2]._content.click(); await sleep(800);
  const em=[...document.querySelectorAll('vaadin-email-field, vaadin-text-field')].find(f=>f.value===email);
  const del=[...document.querySelectorAll('vaadin-button')].find(b=>b.textContent.trim()==='Delete');
  if(!em||!del){log.push('noform '+email);continue;}
  del.click(); await sleep(900); log.push('deleted '+email+' size '+g.size);
}
return log; }

